/* Avaliação Psicológica: estudos dirigidos originais P2 e P1, respostas comentadas próprias e gabaritos oficiais. */
window.PSICO_GUIDES=window.PSICO_GUIDES||{};
window.PSICO_GUIDES.avaliacao=[{"id":"avaliacao-p2","title":"Estudo dirigido — Avaliação Psicológica","subtitle":"20 questões comentadas · anamnese, documentos psicológicos e psicometria","source":"Estudo dirigido para a Prova 2 · Profª Maísa Rigoni · roteiro com gabarito","status":"original","questions":[{"n":1,"question":"As entrevistas são técnicas que compõem o processo de psicodiagnóstico. Sobre a anamnese, é correto\n      afirma:","options":[{"letter":"A","text":"Deve ser realizada no início do processo de psicodiagnóstico, sendo uma técnica que compõe um dos\n              passos mínimos necessários à avaliação psicológica: a coleta de dados."},{"letter":"B","text":"Deve ser realizada no início e ao final do processo de psicodiagnóstico, com vistas a reassegurar a\n              exatidão dos dados, sendo uma técnica que compõe dois dos passos mínimos necessários à avaliação\n              psicológica: a entrevista de dados e a entrevista devolutiva."},{"letter":"C","text":"Deve ser realizada ao longo do processo de psicodiagnóstico, se possível, com diferentes informantes,\n              sendo uma técnica tanto de esclarecimento da queixa inicial quanto de comunicação dos resultados\n              obtidos."},{"letter":"D","text":"Deve ser realizada ao final do processo de psicodiagnóstico, sendo uma técnica de comunicação dos\n              resultados obtidos."}],"answer":"A","topic":"Anamnese e sequência do psicodiagnóstico","explanation":"A anamnese reúne a história da pessoa e o contexto da queixa para orientar hipóteses e decisões sobre o processo. Em geral acontece no início, mas dados históricos podem ser complementados ao longo da avaliação. A devolutiva é outro momento, dedicado a comunicar os resultados.","contrast":"B junta anamnese e devolutiva como se fossem a mesma entrevista; C confunde coleta de informações com comunicação final; D coloca a coleta inicial de história apenas ao final."},{"n":2,"question":"Um dos recursos que contribuem para o psicodiagnóstico é a entrevista de anamnese a partir da\n      investigação do histórico de vida do avaliando, possibilitando maiores entendimentos quanto as queixas\n      apresentadas. Sobre a entrevista de anamnese, assinale a alternativa correlata:","options":[{"letter":"A","text":"Cabe ao profissional de Psicologia buscar informações complementares que possam contribuir com as\n              investigações compreendendo o funcionamento psicológico do indivíduo."},{"letter":"B","text":"É investigado o histórico familiar e social, questões referentes à queixa apresentada, marcos do\n              desenvolvimento e segue a mesma estrutura para todas as faixas etárias."},{"letter":"C","text":"A entrevista de anamnese é realizada com o examinando sem interrupções ou informações advindas de\n              pessoas da família ou afins, independente das capacidades intelectuais."},{"letter":"D","text":"O profissional de Psicologia deverá evitar questionar durante a anamnese aspectos culturais e histórico\n              clínico a fim de preservar possíveis tratamentos medicamentosos."}],"answer":"A","topic":"Amplitude e adaptação da entrevista","explanation":"O profissional deve levantar informações que esclareçam a demanda: desenvolvimento, saúde, família, escola ou trabalho, tratamentos e contexto sociocultural, conforme a idade e a situação. A estrutura da entrevista é flexível e pode envolver familiares ou outros informantes de modo ético.","contrast":"B erra ao impor uma estrutura idêntica a todas as idades; C exclui informantes mesmo quando necessários; D afasta justamente dados culturais e clínicos relevantes."},{"n":3,"question":"A coleta de dados é uma etapa fundamental da avaliação psicopedagógica, que requer a postura de ouvir um\n      relato, sem julgamentos morais, tornando-se um eficiente instrumento para compreender a história do\n      paciente. A obtenção desses dados se dá na entrevista nomeada:","options":[{"letter":"A","text":"Entrevista Operativa Centrada na Aprendizagem."},{"letter":"B","text":"Motivo da Consulta."},{"letter":"C","text":"Devolutiva."},{"letter":"D","text":"Anamnese."},{"letter":"E","text":"Entrevista Escolar."}],"answer":"D","topic":"Identificar a técnica correta","explanation":"A técnica descrita é a anamnese porque procura reconstruir informações sobre história de vida, desenvolvimento e condições atuais sem julgamento moral. Ela não equivale à devolutiva, que comunica resultados, nem a uma entrevista focada apenas em aprendizagem ou vínculo escolar.","contrast":"A focaliza aprendizagem; B investiga a demanda inicial, mas não substitui a história ampliada; C é devolutiva e ocorre na comunicação dos resultados; E se limita ao contexto escolar."},{"n":4,"question":"Sobre a Anamnese assinale a alternativa correta:","options":[{"letter":"A","text":"As informações que a anamnese busca obter não são estabelecidas previamente"},{"letter":"B","text":"Qualquer pessoa tem acesso a anamnese"},{"letter":"C","text":"A finalidade da anamnese é uma compilação de dados preestabelecidos que ofereça uma síntese da\n              história e da situação atual do indivíduo, sua saúde e sua doença"},{"letter":"D","text":"Anamnese busca a avaliação técnica de uma determinada pessoa"},{"letter":"E","text":"Anamnese consiste na solicitação técnica profissional que pode ser prestada de diferentes formas"}],"answer":"C","topic":"Finalidade e organização da anamnese","explanation":"O objetivo é integrar dados previamente planejados sobre história e situação atual, sem transformar a entrevista num questionário inflexível. A seleção de assuntos depende da demanda e da pessoa avaliada, e o registro deve respeitar sigilo e finalidade.","contrast":"A ignora o planejamento prévio; B desconsidera o sigilo profissional; D confunde anamnese com avaliação técnica global; E descreve uma solicitação genérica e não a entrevista."},{"n":5,"question":"Sílvia, 37 anos, procurou um ambulatório de Saúde Mental trazendo uma queixa de ansiedade generalizada.\n   Com o objetivo de fazer um levantamento detalhado da história de desenvolvimento de Sílvia, desde sua\n   infância até o momento presente, a psicóloga realizou uma entrevista:","options":[{"letter":"A","text":"analítica."},{"letter":"B","text":"sistêmica."},{"letter":"C","text":"diagnóstica."},{"letter":"D","text":"de anamnese."}],"answer":"D","topic":"História do desenvolvimento ao longo da vida","explanation":"A psicóloga quer compreender a trajetória desde a infância até o presente; isso caracteriza a entrevista de anamnese. A queixa de ansiedade fornece um ponto de partida, mas não basta para reconstruir desenvolvimento, eventos relevantes e contexto.","contrast":"A, B e C podem designar perspectivas ou funções de outras entrevistas, mas a marca decisiva do enunciado é o levantamento longitudinal da história."},{"n":6,"question":"A avaliação psicológica é um processo técnico e sistemático que utiliza métodos científicos para investigar\n   características psicológicas relevantes ao sujeito e ao contexto, servindo de base para decisões clínicas,\n   educacionais, organizacionais e jurídicas. A escolha adequada dos instrumentos e a elaboração precisa dos\n   documentos técnicos são fundamentais para a validade do processo. Assim, analise as afirmativas a seguir.\n   I.A entrevista psicológica é uma técnica essencial na avaliação, permitindo a coleta de informações sobre a\n   história de vida, sintomas, funcionamento atual e expectativas do indivíduo, servindo de base para a\n   contextualização dos dados obtidos por outros instrumentos.\n   II.O laudo psicológico é um documento opinativo, breve, voltado a responder a uma única questão específica\n   apresentada por terceiros, geralmente sem incluir análise detalhada de instrumentos ou contexto.\n   III.A aplicação de testes psicológicos requer conhecimento técnico e base teórica sólida, devendo ser realizada\n   de acordo com os parâmetros estabelecidos pelo SATEPSI (Sistema de Avaliação de Testes Psicológicos),\n   garantindo validade, fidedignidade e padronização.\n   Está correto o que se afirma em:","options":[{"letter":"A","text":"I, II e III."},{"letter":"B","text":"I e II apenas."},{"letter":"C","text":"I e III apenas."},{"letter":"D","text":"II apenas."}],"answer":"C","topic":"Entrevista, laudo e instrumentos","explanation":"A assertiva I é correta: entrevista contextualiza sintomas, história e outros achados. A II é incorreta porque descreve mais aproximadamente um parecer, não um laudo. A III é correta ao exigir seleção técnica fundamentada dos testes e atenção às diretrizes do SATEPSI e às evidências científicas.","contrast":"A inclui a assertiva II incorreta; B também inclui II e exclui III; D toma II como verdadeira e ignora as demais. A chave é não confundir parecer técnico pontual com laudo de avaliação."},{"n":7,"question":"Conforme o disposto na Resolução nº 6/2019 do CFP, que institui as regras para a elaboração de documentos\n   escritos, produzidos pelo psicólogo no exercício profissional, assinale a alternativa que melhor descreve o\n   documento do tipo Atestado Psicológico.","options":[{"letter":"A","text":"Certifica, com fundamento em um diagnóstico psicológico, uma determinada situação, estado ou\n             funcionamento psicológico, com a finalidade de afirmar as condições psicológicas de quem, por\n             requerimento, o solicita."},{"letter":"B","text":"Registra informações sobre a prestação de serviço realizado ou em realização, abrangendo: 1)\n             comparecimento da pessoa atendida; 2) acompanhamento psicológico realizado ou em realização; e 3)\n             informações sobre tempo de acompanhamento."},{"letter":"C","text":"Considera os condicionantes históricos e sociais da pessoa, grupo ou instituição atendida, comunicando\n             a atuação do psicólogo, podendo gerar orientações, recomendações e encaminhamentos."},{"letter":"D","text":"Resulta da atuação do psicólogo em contexto multiprofissional, podendo ser produzido em conjunto com\n             profissionais de outras áreas."},{"letter":"E","text":"É o resultado de um processo de avaliação psicológica, com finalidade de subsidiar decisões\n             relacionadas ao contexto em que surgiu a demanda."}],"answer":"A","topic":"Atestado psicológico","explanation":"O atestado certifica, com fundamentação psicológica pertinente, determinado estado, condição ou funcionamento psicológico para finalidade específica. É diferente de uma simples declaração de comparecimento, de um relatório de acompanhamento e de um laudo resultante de avaliação psicológica.","contrast":"B corresponde à declaração; C se aproxima do relatório psicológico; D descreve atuação multiprofissional; E define o laudo. Escolha o documento pela finalidade, não pelo tamanho do texto."},{"n":8,"question":"Um relatório psicológico é:","options":[{"letter":"A","text":"Um documento escrito que tem por finalidade registrar, de forma objetiva e sucinta, informações sobre a\n             prestação de serviço realizado ou em realização, abrangendo as seguintes informações: I –\n             Comparecimento da pessoa atendida e seu(sua) acompanhante; II – Acompanhamento psicológico\n             realizado ou em realização; III – Informações sobre tempo de acompanhamento, dias e horários."},{"letter":"B","text":"Um documento que certifica, fundamentado em um diagnóstico psicológico, uma determinada situação,\n             estado ou funcionamento psicológico, com a finalidade de afirmar as condições psicológicas de quem o\n             solicita, pode ainda comunicar o diagnóstico de condições mentais que incapacitem a pessoa atendida."},{"letter":"C","text":"Um documento que considera os condicionantes históricos e sociais da pessoa, grupo ou instituição\n             atendida, podendo também ter caráter informativo, visa comunicar a atuação profissional da(o)\n             psicóloga(o) em diferentes processos de trabalho já desenvolvidos ou em desenvolvimento, não tendo\n             como finalidade produzir diagnóstico psicológico."},{"letter":"D","text":"O resultado de um processo de avaliação psicológica, com finalidade de subsidiar decisões relacionadas\n             ao contexto em que surgiu a demanda."},{"letter":"E","text":"O documento psicológico mais objetivo e sucinto entre todos, deve responder a solicitações pontuais que\n            visam informar situações que envolvem dia(s), horários e tempo de atendimento da(o) paciente/cliente\n            e/ou da pessoa que a(o) acompanha."}],"answer":"C","topic":"Relatório psicológico","explanation":"O relatório comunica atuação profissional, processos de trabalho, informações relevantes, conclusões e recomendações, considerando os condicionantes sociais e históricos. Não tem como finalidade produzir diagnóstico psicológico; caso decorra de avaliação com finalidade diagnóstica específica, o documento pertinente pode ser o laudo.","contrast":"A e E definem declaração; B caracteriza atestado; D caracteriza laudo. Relatório é comunicação de atuação, não apenas um comprovante nem um diagnóstico."},{"n":9,"question":"O documento psicológico resultante de um processo de avaliação psicológica que tem por finalidade\n    subsidiar decisões relacionadas ao contexto em que surgiu a demanda é denominado","options":[{"letter":"A","text":"relatório psicológico."},{"letter":"B","text":"declaração psicológica."},{"letter":"C","text":"atestado psicológico."},{"letter":"D","text":"laudo psicológico."},{"letter":"E","text":"parecer psicológico."}],"answer":"D","topic":"Laudo psicológico","explanation":"Laudo é o documento derivado de um processo de avaliação psicológica, elaborado para subsidiar decisões relacionadas à demanda. Deve conter método, análise fundamentada e conclusão proporcional aos dados, preservando as informações estritamente necessárias.","contrast":"Relatório descreve atuação; declaração registra atendimento; atestado certifica condição; parecer responde a questão-problema. O vínculo com a avaliação psicológica identifica o laudo."},{"n":10,"question":"A elaboração de documentos psicológicos no Brasil é regida por diretrizes específicas que visam garantir a\n    qualidade, a ética e a legalidade das informações prestadas. Considerando os princípios fundamentais\n    envolvidos nesse processo, assinale a afirmativa correta.","options":[{"letter":"A","text":"Os documentos psicológicos podem ser elaborados com identificação implícita do profissional\n            responsável pela avaliação e pela elaboração do documento."},{"letter":"B","text":"A inserção de informações pessoais secundárias nos documentos psicológicos é aceitável desde que o\n            profissional considere essas informações como potencialmente úteis."},{"letter":"C","text":"A ausência de assinatura ou carimbo do profissional responsável é indiferente à validade dos documentos\n            psicológicos, haja vista a garantia de clareza, precisão e fidedignidade das informações."},{"letter":"D","text":"A elaboração de documentos psicológicos deve seguir as normas estabelecidas pelo Conselho Federal\n            de Psicologia (CFP), assegurando a clareza, a precisão e a confidencialidade das informações."},{"letter":"E","text":"Nos documentos psicológicos é permitido utilizar linguagem técnica complexa, visando resguardar a\n            fidedignidade e a validade das informações, sendo dispensada a explicação de termos para leigos."}],"answer":"D","topic":"Ética e redação de documentos","explanation":"A escrita deve seguir a Resolução CFP nº 06/2019 e os princípios de confidencialidade, identificação profissional, pertinência, clareza e fundamentação. O destinatário precisa compreender a informação necessária, sem exposição excessiva de dados pessoais.","contrast":"A e C fragilizam identificação e validade; B trata como aceitáveis dados secundários sem necessidade demonstrada; E transforma jargão incompreensível em suposta qualidade técnica."},{"n":11,"question":"Ao elaborar um parecer, de acordo com a Resolução do Conselho Federal de Psicologia – CFP nº 06/2019, o\n    psicólogo deve:","options":[{"letter":"A","text":"Apresentar seu posicionamento técnico, de forma fundamentada, sobre uma questão específica,\n            respondendo à demanda que motivou a solicitação do parecer."},{"letter":"B","text":"Expressar sua opinião sobre a questão apresentada, com base em suas convicções pessoais e valores\n            morais, para oferecer uma perspectiva singular sobre o caso."},{"letter":"C","text":"Priorizar a linguagem técnica e complexa para garantir a precisão das informações, mesmo que isso\n            dificulte a compreensão por parte dos leitores."},{"letter":"D","text":"Utilizar testes psicológicos como único instrumento de coleta de dados, garantindo a objetividade e a\n            cientificidade do parecer."}],"answer":"A","topic":"Parecer como posicionamento técnico","explanation":"O parecer responde de maneira fundamentada a uma questão específica, inclusive quando se examina criticamente uma questão técnica ou documento psicológico. É necessário explicitar a demanda e sustentar a conclusão em conhecimento psicológico, não em preferências pessoais.","contrast":"B substitui técnica por moral pessoal; C sacrifica a compreensibilidade; D reduz a análise a testes como fonte única, o que não é obrigatório nem suficiente."},{"n":12,"question":"A Resolução nº 6, de 29 de março de 2019, do Conselho Federal de Psicologia, institui regras para a\n    elaboração de documentos escritos produzidos pelo psicólogo no exercício profissional. Nesse contexto, o\n    relatório multiprofissional é composto por quais itens?","options":[{"letter":"A","text":"Identificação, descrição da demanda, procedimento, análise, conclusão e referências."},{"letter":"B","text":"Título, nome da pessoa ou instituição atendida, nome do solicitante, finalidade e descrição das condições\n            psicológicas do beneficiário do serviço psicológico."},{"letter":"C","text":"Identificação, descrição da demanda, procedimento, análise e conclusão."},{"letter":"D","text":"Identificação, descrição da demanda, análise, conclusão e referências."}],"answer":"C","topic":"Estrutura do relatório multiprofissional","explanation":"Conforme o roteiro, a estrutura envolve identificação, descrição da demanda, procedimentos, análise e conclusão. A contribuição da Psicologia deve ser distinguida com clareza e observância do sigilo na atuação compartilhada.","contrast":"A acrescenta referências como item obrigatório nessa enumeração; B descreve outros elementos documentais; D omite procedimentos e altera a estrutura. Não transportar automaticamente a estrutura do laudo para todo documento."},{"n":13,"question":"Considere as afirmações abaixo, que versam sobre a elaboração de laudos, e aponte a alternativa CORRETA.","options":[{"letter":"A","text":"A “Descrição da Demanda” é um item facultativo em um laudo psicológico, sua inclusão dependerá do\n            tipo de avaliação psicológica para a qual o laudo em questão se destina."},{"letter":"B","text":"A “Finalidade”, item obrigatório na “Identificação”, deve apresentar uma descrição da razão ou motivo\n            pelo qual o laudo foi solicitado."},{"letter":"C","text":"Quando a/o profissional de Psicologia atua em equipe multidisciplinar, deverá escrever um laudo em\n            separado do redigido pela equipe, de maneira a salvaguardar o sigilo profissional."},{"letter":"D","text":"As Referências Bibliográficas, utilizadas como suporte teórico–metodológico, podem ou não ser incluídas\n            no laudo, em caso positivo, deverão constar ao final do documento."}],"answer":"B","topic":"Finalidade dentro da identificação do laudo","explanation":"A finalidade explicita por que o laudo foi solicitado. Descrição da demanda é obrigatória; procedimentos, análise, conclusão e referências pertinentes completam a estrutura normativa. É importante diferenciar a solicitação do problema investigado e as conclusões técnicas obtidas.","contrast":"A torna facultativa a descrição da demanda; C impõe laudo separado sempre que houver equipe, o que não decorre automaticamente da norma; D trata referências utilizadas como opcionalmente omitidas."},{"n":14,"question":"De acordo com a Resolução CFP nº 06/2019, a Declaração é um documento psicológico destinado a registrar,\n    de maneira objetiva e sucinta, informações sobre a prestação de serviços psicológicos. Considerando suas\n    características e limitações, assinale a alternativa CORRETA:","options":[{"letter":"A","text":"A Declaração pode apresentar informações sobre sintomas e estados psicológicos, desde que sejam\n            relevantes para justificar o acompanhamento."},{"letter":"B","text":"A Declaração tem como finalidade apresentar os resultados de uma avaliação psicológica, incluindo\n            hipóteses diagnósticas e recomendações."},{"letter":"C","text":"A Declaração pode registrar o comparecimento da pessoa atendida, a realização de acompanhamento\n            psicológico e informações sobre dias, horários e duração do atendimento."},{"letter":"D","text":"A Declaração deve apresentar uma descrição detalhada dos procedimentos técnicos utilizados durante\n            o acompanhamento psicológico."},{"letter":"E","text":"A Declaração pode substituir o Atestado Psicológico quando houver necessidade de justificar\n            afastamento das atividades profissionais por condições psicológicas."}],"answer":"C","topic":"Limites da declaração","explanation":"A declaração registra objetivamente prestação de serviço, comparecimento e informações de período, dias ou horários, sem expor diagnóstico ou detalhes clínicos. Sua função administrativa é comprovar o atendimento, não resumir uma avaliação.","contrast":"A inclui estados e sintomas indevidamente; B converte declaração em laudo; D exige procedimentos detalhados; E substitui atestado sem atender à finalidade de certificação psicológica."},{"n":15,"question":"Uma psicóloga recebe a solicitação de uma paciente que necessita comprovar à instituição de ensino seu\n    comparecimento a atendimentos psicológicos semanais. Considerando as orientações da Resolução CFP\n    nº 06/2019 para a elaboração da Declaração, assinale a alternativa CORRETA.","options":[{"letter":"A","text":"A profissional deverá apresentar, além dos dias e horários dos atendimentos, uma breve descrição das\n            dificuldades emocionais que motivaram a procura pelo serviço."},{"letter":"B","text":"A profissional poderá omitir a finalidade do documento, desde que constem a identificação da paciente e\n            as informações referentes aos atendimentos realizados."},{"letter":"C","text":"A profissional deverá incluir os instrumentos psicológicos utilizados, a frequência dos atendimentos e\n            uma síntese da evolução clínica da paciente."},{"letter":"D","text":"A profissional deverá elaborar o documento com o título \"Declaração\", identificar a paciente, especificar\n            a finalidade e informar os dados pertinentes aos atendimentos, encerrando-o com local, data,\n            identificação profissional, número de inscrição no CRP e assinatura."},{"letter":"E","text":"A profissional deverá emitir um Atestado Psicológico, pois a Declaração não pode ser utilizada para\n            comprovar comparecimento a atendimentos psicológicos."}],"answer":"D","topic":"Declaração para instituição de ensino","explanation":"Quando a instituição precisa comprovar comparecimento, usa-se declaração com título, identificação pertinente, finalidade, dados necessários do atendimento, local e data, identificação profissional, CRP e assinatura. Dados clínicos não são necessários para provar presença.","contrast":"A e C expõem informações clínicas e instrumentos que não servem à finalidade; B omite a finalidade; E descarta o documento apropriado e escolhe atestado sem necessidade."},{"n":16,"question":"A Resolução CFP nº 06/2019 estabelece diretrizes para a elaboração de documentos psicológicos,\n    considerando suas finalidades, características e especificidades técnicas. Com base nessa normativa,\n    assinale a alternativa CORRETA.","options":[{"letter":"A","text":"A Declaração e o Atestado Psicológico possuem a mesma finalidade, podendo ambos apresentar\n            informações sobre sintomas, estados psicológicos e hipóteses diagnósticas."},{"letter":"B","text":"O Relatório Psicológico tem como finalidade principal estabelecer um diagnóstico psicológico, devendo\n            apresentar obrigatoriamente os resultados dos instrumentos utilizados durante a avaliação."},{"letter":"C","text":"O Laudo Psicológico é elaborado a partir de um processo de avaliação psicológica, enquanto o Parecer\n            Psicológico consiste em uma análise técnica destinada a responder a uma questão-problema ou\n            examinar documentos psicológicos questionados."},{"letter":"D","text":"O Relatório Multiprofissional deve apresentar exclusivamente informações produzidas pela(o)\n            psicóloga(o), sendo vedada a participação de profissionais de outras áreas em sua elaboração."},{"letter":"E","text":"O Parecer Psicológico deve ser elaborado obrigatoriamente após um processo de avaliação psicológica,\n            apresentando os procedimentos realizados, os resultados obtidos e as hipóteses diagnósticas."}],"answer":"C","topic":"Distinção entre laudo e parecer","explanation":"Laudo é produto de processo de avaliação psicológica; parecer é resposta fundamentada a questão-problema ou análise técnica, inclusive de documento questionado. Relatório, declaração e atestado cumprem finalidades próprias e não são intercambiáveis.","contrast":"A iguala declaração e atestado; B atribui diagnóstico obrigatório ao relatório; D exclui indevidamente outros profissionais do relatório multiprofissional; E exige do parecer os passos de uma avaliação integral."},{"n":17,"question":"A fidedignidade, também denominada precisão ou confiabilidade, constitui uma propriedade psicométrica\n    fundamental para a qualidade dos testes psicológicos. Considerando esse conceito e os métodos utilizados\n    para investigá-lo, assinale a alternativa CORRETA.","options":[{"letter":"A","text":"A fidedignidade refere-se à capacidade de um instrumento avaliar adequadamente o construto\n            psicológico que se propõe a mensurar."},{"letter":"B","text":"A fidedignidade é determinada exclusivamente pela quantidade de itens de um teste, independentemente\n            das condições de aplicação e das características dos participantes."},{"letter":"C","text":"A fidedignidade corresponde à estabilidade e à consistência dos resultados de um instrumento, podendo\n            ser investigada por métodos como teste-reteste, formas paralelas e consistência interna."},{"letter":"D","text":"Um instrumento que apresenta elevada fidedignidade necessariamente possui evidências suficientes de\n            validade, pois resultados consistentes garantem a mensuração adequada do construto."},{"letter":"E","text":"A fidedignidade é estabelecida por meio da comparação dos escores individuais com os resultados\n            obtidos por uma amostra normativa representativa da população."}],"answer":"C","topic":"Precisão ou fidedignidade","explanation":"Precisão indica estabilidade ou consistência de resultados sob condições pertinentes. Pode ser estudada por teste-reteste, equivalência de formas e consistência interna. Um teste pode ser consistente e, mesmo assim, medir o construto inadequado.","contrast":"A define validade; B reduz precisão ao número de itens; D supõe que fidedignidade garante validade; E descreve comparação com normas."},{"n":18,"question":"A padronização e a normatização são procedimentos fundamentais para assegurar a qualidade da aplicação\n    e da interpretação dos testes psicológicos. Considerando as características desses processos, assinale a\n    alternativa CORRETA.","options":[{"letter":"A","text":"A padronização refere-se à elaboração de tabelas normativas, enquanto a normatização estabelece as\n            condições ambientais e os procedimentos de aplicação dos testes."},{"letter":"B","text":"A padronização estabelece condições uniformes de aplicação e correção dos instrumentos, enquanto a\n           normatização permite interpretar os resultados individuais a partir de sua comparação com uma amostra\n           representativa da população."},{"letter":"C","text":"A normatização permite que os resultados de um instrumento sejam interpretados utilizando tabelas\n           normativas de qualquer população, desde que o teste avalie o mesmo construto psicológico."},{"letter":"D","text":"A padronização permite que o profissional modifique livremente as instruções e os procedimentos de\n           aplicação, desde que considere as características individuais da pessoa avaliada."},{"letter":"E","text":"A padronização e a normatização são procedimentos equivalentes, ambos destinados exclusivamente a\n           garantir a estabilidade dos resultados obtidos em diferentes aplicações."}],"answer":"B","topic":"Padronização versus normatização","explanation":"Padronização é a uniformização das instruções, condições, aplicação e correção. Normatização é a construção de parâmetros comparativos baseados em amostra pertinente para interpretar escores. Ambas importam, mas não têm a mesma finalidade.","contrast":"A inverte os conceitos; C autoriza normas de população não correspondente; D permite mudanças arbitrárias de aplicação; E afirma equivalência entre processos distintos."},{"n":19,"question":"As evidências de validade constituem um dos principais critérios para avaliar a qualidade dos testes\n    psicológicos. Considerando esse conceito, assinale a alternativa CORRETA.","options":[{"letter":"A","text":"Referem-se à capacidade de um instrumento produzir resultados consistentes e estáveis ao longo de\n           diferentes aplicações."},{"letter":"B","text":"Referem-se às informações que demonstram se um teste psicológico realmente avalia aquilo que se\n           propõe a medir."},{"letter":"C","text":"Consistem na uniformização dos procedimentos de aplicação, correção e interpretação dos testes\n           psicológicos."},{"letter":"D","text":"Referem-se à comparação dos resultados individuais com os escores obtidos por uma amostra\n           representativa da população."},{"letter":"E","text":"Correspondem à capacidade de um instrumento produzir resultados semelhantes, independentemente\n           das características da população avaliada."}],"answer":"B","topic":"Evidências de validade","explanation":"Validade envolve evidências e argumentos que sustentam a interpretação dos resultados para determinado uso. Não é apenas uma característica binária de um teste: depende do construto, da população e da finalidade da interpretação.","contrast":"A descreve precisão; C descreve padronização; D descreve normas; E não corresponde à análise contextual de validade. Um teste confiável não é automaticamente válido para todo uso."},{"n":20,"question":"A construção de instrumentos psicológicos envolve diferentes etapas e cuidados para garantir que sejam\n    adequados à população que será avaliada. Considerando esse processo, assinale a alternativa CORRETA.","options":[{"letter":"A","text":"A construção de um instrumento deve considerar apenas a quantidade de itens, independentemente de\n           sua fundamentação teórica."},{"letter":"B","text":"A elaboração dos itens deve priorizar uma linguagem técnica e complexa, independentemente das\n           características da população-alvo."},{"letter":"C","text":"A construção de instrumentos deve considerar a fundamentação teórica do construto, as características\n           culturais, a faixa etária e o nível de compreensão da população-alvo."},{"letter":"D","text":"A construção de um instrumento dispensa a revisão da literatura, desde que os itens sejam elaborados\n           por profissionais experientes."},{"letter":"E","text":"A construção de instrumentos deve seguir os mesmos critérios para todas as populações, sem\n           necessidade de considerar diferenças culturais ou etárias."}],"answer":"C","topic":"Construção e adaptação dos instrumentos","explanation":"A construção exige fundamentação teórica, definição do construto e adequação dos itens à cultura, idade e capacidade de compreensão da população. Depois, investigam-se propriedades psicométricas, procedimentos e uso adequado. Não basta produzir muitos itens.","contrast":"A ignora fundamento teórico; B desconsidera linguagem acessível; D dispensa revisão de literatura; E ignora diferenças culturais e etárias."}]},{"id":"avaliacao-p1","title":"Estudo dirigido — Avaliação Psicológica (P1)","subtitle":"19 questões respondidas · profissão, Resolução 31/2022, testes e entrevista","source":"Estudo Dirigido AP – P1 · Profª Maísa Rigoni · errata oficial de gabarito utilizada","status":"original","questions":[{"n":1,"question":"Analise as afirmações a seguir, e assinale V para as alterativas corretas e F para as incorretas: ( ) Inicialmente, os primeiros cursos de graduação em Psicologia do Brasil tiveram como docentes psicólogos já formados, e, somente mais tarde médicos e pedagogos assumiram parte das disciplinas. ( ) A criação do Conselho Federal de Psicologia (CFP) e das suas sucursais ocorreu em 1962, no mesmo ano da regulamentação da profissão. ( ) A Lei Federal nº 4.119/1962, que regulamentou a profissão de Psicólogo no Brasil, estabeleceu, como funções privativas do psicólogo a utilização de métodos e de técnicas psicológicas para diagnóstico psicológico, orientação e seleção profissional, orientação psicopedagógica e solução de problemas de ajustamento. ( ) A Resolução CFP nº 9/2018 regulamentou o SATEPSI e as diretrizes da avaliação psicológica, mas foi posteriormente revogada pela Resolução CFP nº 31/2022. Assinale a alternativa que apresenta a sequência correta:","options":[{"letter":"A","text":"V – F – V – V"},{"letter":"B","text":"F – V – V – F"},{"letter":"C","text":"V – F – F – V"},{"letter":"D","text":"F – F – V – V"},{"letter":"E","text":"V – V – F – F"}],"answer":"D","topic":"História da profissão e normas","explanation":"Sequência da questão: F, F, V, V. A Psicologia brasileira começou com contribuição de médicos, educadores e pesquisadores antes da formação universitária regulamentada; a Lei 4.119/1962 define funções privativas; e a Resolução CFP 31/2022 revogou a 09/2018.","contrast":"A criação dos Conselhos profissionais não ocorreu junto com a lei de 1962; o sistema CFP/CRPs foi instituído por legislação posterior. A alternativa D reúne essas quatro avaliações."},{"n":2,"question":"Com base na Resolução CFP nº 31/2022, analise as afirmações a seguir, e assinale V para as alterativas corretas e F para as incorretas: ( ) A Resolução CFP nº 31/2022 define a Avaliação Psicológica como um processo estruturado de investigação de fenômenos psicológicos, que deve obrigatoriamente abranger métodos, técnicas e instrumentos, sempre vinculados às demandas, às condições e às finalidades específicas. ( ) O uso de qualquer tipo de teste psicológico no exercício profissional é privativo do psicólogo, mesmo quando não há respaldo na Lei nº 4.119/1962. ( ) O psicólogo tem a prerrogativa de escolher os métodos, técnicas e instrumentos na Avaliação Psicológica, desde que fundamentados em literatura científica e nas normativas vigentes do CFP. ( ) Os estudos de validade, precisão e normas dos testes psicológicos têm prazo máximo de vigência de 20 anos, contados da data de aprovação pela Plenária do CFP. Assinale a alternativa que apresenta a sequência correta:","options":[{"letter":"A","text":"V – V – V – F"},{"letter":"B","text":"V – F – V – F"},{"letter":"C","text":"F – V – V – F"},{"letter":"D","text":"V – F – F – V"},{"letter":"E","text":"V – V – F – F"}],"answer":"B","topic":"Diretrizes da Resolução 31/2022","explanation":"Sequência: V, F, V, F. Avaliação psicológica é processo estruturado articulado à demanda, e a escolha de técnicas precisa de fundamento científico e respeito às normas. Não se conclui exclusividade de todo e qualquer teste sem verificar a norma, e a frase final sobre 20 anos de vigência é incorreta.","contrast":"A validade e precisão de testes são avaliadas conforme prazos e critérios definidos pelo CFP; não confundir regulamentos históricos ou regras de revisão técnica com afirmações absolutas."},{"n":3,"question":"Com base nos seus conhecimentos sobre a Resolução CFP nº 31/2022, analise as afirmativas a seguir: I. As fontes fundamentais de informação correspondem a testes e técnicas de uso exclusivo do psicólogo. II. As fontes complementares de informação incluem testes e técnicas que não são de uso exclusivo do psicólogo, mas que possuem respaldo na literatura científica. III. Os estudos de validade, precisão e normas dos testes psicológicos possuem prazo máximo de 15 anos, contados da data de aprovação pela Plenária do CFP. IV. As fontes complementares de informação podem substituir totalmente as fontes fundamentais no processo de Avaliação Psicológica, desde que tenham respaldo científico. Estão corretas as seguintes afirmativas:","options":[{"letter":"A","text":"Apenas as afirmativas 1, 2 e 3."},{"letter":"B","text":"Apenas as afirmativas 1 e 4."},{"letter":"C","text":"Apenas as afirmativas 2, 3 e 4."},{"letter":"D","text":"Apenas as afirmativas 1 e 3."},{"letter":"E","text":"Todas as afirmativas estão corretas."}],"answer":"A","topic":"Fontes fundamentais e complementares","explanation":"O gabarito da professora considera corretas I, II e III, com IV falsa. Fontes fundamentais incluem métodos e técnicas de uso profissional pertinente; fontes complementares ampliam a informação, mas não substituem integralmente a fundamentação necessária. A alternativa correta é a A.","contrast":"Não se deve planejar avaliação apenas com fonte complementar por conveniência. A interpretação depende da resolução e dos critérios vigentes no momento da aplicação."},{"n":4,"question":"A avaliação psicológica é um processo que envolve tanto a definição conceitual de sua função quanto a explicitação de seus objetivos práticos. Considerando as descrições apresentadas, assinale a alternativa correta sobre a definição e o objetivo da Avaliação Psicológica:","options":[{"letter":"A","text":"A Avaliação Psicológica é definida como uma técnica padronizada, destinada, exclusivamente, para medir funções cognitivas, sendo seu objetivo principal classificar os indivíduos em categorias diagnósticas, previamente estabelecidas."},{"letter":"B","text":"A definição de Avaliação Psicológica envolve a descrição e a compreensão do indivíduo, em suas diferentes características, abrangendo aspectos cognitivos, de personalidade, adaptativos e desadaptativos, enquanto seu objetivo consiste em levantar hipóteses ou diagnósticos que auxiliem em decisões específicas sobre determinada situação."},{"letter":"C","text":"Define-se Avaliação Psicológica como um conjunto de entrevistas que investigam apenas sintomas psicopatológicos, tendo como objetivo central o estabelecimento de prognóstico clínico a partir da exclusão de outras hipóteses diagnósticas."},{"letter":"D","text":"A Avaliação Psicológica se define como um protocolo exclusivo da área clínica, cujo objetivo é determinar a aptidão do indivíduo para tratamentos psicoterápicos de longa duração."},{"letter":"E","text":"A definição da Avaliação Psicológica refere-se à descrição das atividades realizadas pelo psicólogo durante o processo, enquanto o objetivo diz respeito à produção de resultados estatísticos que sejam aceitos por agências de fomento à pesquisa científica."}],"answer":"B","topic":"Definição e finalidade da avaliação","explanation":"A avaliação psicológica investiga e compreende fenômenos psicológicos relevantes em dado contexto para apoiar decisões específicas. Não é exclusivamente clínica, não consiste só em testes padronizados, nem tem como objetivo apenas classificar pessoas. A letra B relaciona compreensão ampla e finalidade contextualizada.","contrast":"Diferencie definição do processo (investigação estruturada) e objetivo (responder à demanda). Entrevistas, observações e testes podem participar da integração de evidências."},{"n":5,"question":"O processo de Avaliação Psicológica é estruturado em diferentes etapas que se articulam entre si, da demanda inicial até a devolutiva dos resultados. Considerando os passos apresentados, assinale a alternativa correta:","options":[{"letter":"A","text":"O contrato de trabalho com o cliente deve ser estabelecido após a análise e interpretação dos resultados, pois só nesse momento é possível definir com clareza os limites e as responsabilidades do psicólogo e do avaliado."},{"letter":"B","text":"A execução do plano de trabalho ocorre antes da definição do método ou das estratégias de avaliação, já que é a aplicação prática que orienta a posterior escolha dos instrumentos mais adequados."},{"letter":"C","text":"A análise, interpretação e triangulação dos resultados compreende a integração dos dados provenientes de entrevistas, testes e observações, constituindo etapa anterior à elaboração do documento psicológico, que deve ser arquivado impresso por, no mínimo, cinco anos e posteriormente incinerado."},{"letter":"D","text":"O encaminhamento e a demanda referem-se exclusivamente ao contexto clínico, incluindo psicodiagnóstico e psicoterapia, não abrangendo outras áreas, como a jurídica ou organizacional."},{"letter":"E","text":"A devolução dos resultados ocorre antes da elaboração do documento psicológico, pois o laudo, relatório ou atestado só deve ser confeccionado após o retorno das informações ao cliente ou instituição solicitante."}],"answer":"C","topic":"Etapas da avaliação e integração de dados","explanation":"O roteiro marca a letra C: entrevistas, observações e testes, quando utilizados, devem ser analisados em conjunto antes da redação do documento, segundo a finalidade da avaliação. Contrato, estratégias e planejamento ocorrem antes da execução, e a devolutiva encerra a comunicação dos resultados.","contrast":"A redação inclui observação sobre guarda e descarte que precisa ser lida com as normas atuais de sigilo, registro documental e preservação; não generalizar 'incineração automática' como regra para todo documento."},{"n":6,"question":"No processo de Avaliação Psicológica, a utilização de testes psicológicos é uma prática que exige critérios técnicos e éticos. Considerando as funções e as limitações do uso desses instrumentos, assinale a alternativa correta:","options":[{"letter":"A","text":"O uso de testes é obrigatório em qualquer processo de avaliação psicológica, uma vez que somente eles são capazes de fornecer informações confiáveis e válidas sobre construtos não observáveis diretamente."},{"letter":"B","text":"Os testes psicológicos substituem a entrevista clínica, visto que apresentam maior objetividade e reduzem o risco de interpretações equivocadas por parte do avaliador."},{"letter":"C","text":"Embora os testes sejam instrumentos padronizados, seu uso é opcional: podem ser dispensados quando a entrevista já oferece dados suficientes, sendo considerados ferramentas auxiliares e não exclusivas do processo avaliativo."},{"letter":"D","text":"A principal limitação dos testes psicológicos é a falta de objetividade, já que os resultados obtidos tendem a refletir a subjetividade do avaliador em maior grau do que os dados colhidos por meio de entrevistas."},{"letter":"E","text":"A justificativa para o uso de testes se concentra unicamente na eficiência temporal e de custos, sem relação com a precisão ou a validade científica dos resultados obtidos."}],"answer":"C","topic":"Quando e por que usar testes","explanation":"Os testes podem ser instrumentos importantes, mas a avaliação psicológica não se resume a eles. A escolha depende da pergunta, da evidência científica, da população e do contexto. O gabarito seleciona C, que os trata como instrumentos auxiliares quando pertinentes.","contrast":"A e B os tornam obrigatórios e substitutos da entrevista; D ignora seus procedimentos objetivos; E despreza validade e precisão. A decisão de dispensar testes precisa ser tecnicamente justificada."},{"n":7,"question":"A Avaliação Psicológica abrange diferentes contextos e objetivos, indo desde demandas educacionais até aplicações específicas em segurança pública. Com base nessas áreas assinale a alternativa incorreta:","options":[{"letter":"A","text":"Na área educacional, a Avaliação Psicológica pode ter como foco a identificação de Transtorno de Déficit de Atenção com Hiperatividade (TDAH) e a realização de processos de orientação vocacional ou profissional."},{"letter":"B","text":"Na área organizacional, a Avaliação Psicológica pode estar relacionada à concursos públicos, à ascensão profissional, aos processos de seleção e às avaliações específicas, voltadas à recolocação do trabalhador no mercado de trabalho."},{"letter":"C","text":"No âmbito clínico, o Psicodiagnóstico caracteriza-se por processos mais longos ( de 6 à 12 encontros), envolvendo a avaliação da personalidade e das funções cognitivas, enquanto a Avaliação Neuropsicológica é geralmente breve (de 4 à 6 encontros)."},{"letter":"D","text":"Na área jurídica, a Avaliação Psicológica restringe-se, exclusivamente, à perícia judicial, não contemplando outras modalidades, como parecer psicológico ou avaliação de perfil."},{"letter":"E","text":"A Avaliação Psicológica também pode estar vinculada ao porte de arma de fogo."}],"answer":"D","topic":"Contextos da avaliação","explanation":"A alternativa incorreta é D: atuação psicológica em segurança pública não se limita à perícia judicial, podendo incluir avaliações de perfil e outras modalidades legalmente previstas. A avaliação também existe em contextos educacionais, clínicos, organizacionais e de porte de arma, conforme regras aplicáveis.","contrast":"O enunciado pede a alternativa INCORRETA. Não confundir o contexto de atuação com um único procedimento; os critérios e limites diferem conforme o cenário profissional."},{"n":8,"question":"Os testes psicológicos constituem um dos principais instrumentos da Avaliação Psicológica, mas seu uso exige rigor técnico e contextualização. Com base nessas informações, assinale a alternativa correta:","options":[{"letter":"A","text":"O resultado de um teste psicológico, quando aplicado de forma padronizada, é suficiente para estabelecer diagnóstico conclusivo, dispensando outros métodos ou técnicas complementares."},{"letter":"B","text":"Para que um teste seja considerado adequado, basta apresentar evidências de validade e de fidedignidade, sendo a padronização e a normatização aspectos secundários e não obrigatórios."},{"letter":"C","text":"Os testes psicológicos medem diretamente construtos, como inteligência e ansiedade, razão pela qual não necessitam de processo de elaboração complexo."},{"letter":"D","text":"A Avaliação Psicológica integra diferentes métodos e técnicas, sendo os testes componentes relevantes, porém não exclusivos, devendo seus resultados ser contextualizados junto a outros dados obtidos."},{"letter":"E","text":"No Brasil, segundo a ADI 3481, tanto os manuais quanto os protocolos de aplicação e de correção de testes, podem ser livremente adquiridos por qualquer pessoa, independentemente de possuir formação em Psicologia e CRP ativo e regular."}],"answer":"D","topic":"Testes e interpretação contextualizada","explanation":"Um escore isolado não basta para uma conclusão sobre uma pessoa. A aplicação de testes requer pertinência, evidências psicométricas, aplicação padronizada, integração com outras informações e cuidados éticos. A letra D contém a formulação compatível com essa exigência.","contrast":"Evitar inferências automáticas, uso fora do público-alvo ou compartilhamento indevido de materiais restritos. Laudos não devem transformar números em rótulos sem fundamentação."},{"n":9,"question":"O que significa a sigla SATEPSI?","options":[],"answer":null,"topic":"O significado de SATEPSI","explanation":"SATEPSI significa Sistema de Avaliação de Testes Psicológicos. É o sistema vinculado ao Conselho Federal de Psicologia que divulga pareceres técnicos sobre instrumentos e informa as condições de utilização profissional.","contrast":"Lembra: SATEPSI avalia a qualidade dos testes e divulga pareceres; não é um serviço de aplicar testes em pacientes."},{"n":10,"question":"O SATEPSI desempenha um papel fundamental na regulação e na qualificação do uso dos testes psicológicos, no Brasil. Com base nos seus conhecimentos, assinale a alternativa correta.","options":[{"letter":"A","text":"O SATEPSI tem como principal função aplicar testes em âmbito nacional, a fim de garantir uniformidade nos diagnósticos realizados por psicólogos em diferentes regiões do país."},{"letter":"B","text":"Entre as funções do SATEPSI, destacam-se a qualificação dos instrumentos psicológicos quanto aos parâmetros psicométricos mínimos, a certificação dos testes como favoráveis ou desfavoráveis, e a regulamentação do uso e da comercialização comercialização desses instrumentos."},{"letter":"C","text":"O SATEPSI atua exclusivamente na divulgação de manuais de testes e de protocolos, não interferindo nos critérios de validade, de fidedignidade ou de padronização dos instrumentos psicológicos."},{"letter":"D","text":"O SATEPSI é responsável por fiscalizar diretamente os profissionais de Psicologia que utilizam testes, emitindo sanções administrativas em casos de uso inadequado ou antiético."},{"letter":"E","text":"O SATEPSI se limita a recomendar boas práticas na construção de instrumentos psicológicos, sem vínculo com princípios éticos do Código de Ética do Psicólogo ou com parâmetros científicos."}],"answer":"B","topic":"Função e qualidade do SATEPSI","explanation":"A letra B descreve a função técnico-científica de avaliar a qualidade dos testes e oferecer referências para uso responsável. O sistema não aplica testes por todo o país, não é apenas órgão punitivo e não substitui o julgamento clínico do psicólogo.","contrast":"O profissional continua responsável por escolher o instrumento pertinente e conferir se há parecer favorável, normas adequadas e condições de aplicação."},{"n":11,"question":"O SATEPSI surgiu em resposta à demandas sociais, éticas e científicas relacionadas ao uso dos instrumentos psicológicos no Brasil. Considerando o contexto de sua criação, assinale a alternativa correta:","options":[{"letter":"A","text":"O SATEPSI foi criado exclusivamente para substituir os Conselhos Regionais de Psicologia na fiscalização dos profissionais que aplicavam testes em processos seletivos de concursos públicos."},{"letter":"B","text":"O SATEPSI surgiu diante do elevado número de questionamentos éticos e judiciais sobre a Avaliação Psicológica, especialmente em exames psicotécnicos para CNH e em concursos públicos, além da constatação da insuficiência de estudos de validade dos instrumentos utilizados."},{"letter":"C","text":"O SATEPSI foi instituído unicamente para uniformizar a aplicação de testes projetivos em contextos clínicos, sem relação com questões jurídicas ou éticas."},{"letter":"D","text":"O SATEPSI foi criado porque os Conselhos Regionais de Psicologia não possuíam mais autonomia para registrar testes psicológicos, passando essa responsabilidade diretamente ao Conselho Federal de Psicologia."},{"letter":"E","text":"O SATEPSI teve origem para regulamentar o ensino de Psicologia nas universidades, em virtude da ausência de disciplinas específicas sobre Avaliação Psicológica na formação acadêmica."}],"answer":"B","topic":"Razões históricas para criação do SATEPSI","explanation":"O sistema surgiu para responder a questões éticas e científicas relativas à qualidade e ao uso de instrumentos psicológicos, oferecendo avaliação técnica organizada. A alternativa B é a do gabarito.","contrast":"O projeto não se limita ao ensino universitário, a concursos ou à substituição de Conselhos. O sentido central é proteger a qualidade das decisões derivadas de avaliações."},{"n":12,"question":"Qual a diferença entre um Teste Psicológico Favorável e um Teste Psicológico Desfavorável?","options":[],"answer":null,"topic":"Testes favoráveis e desfavoráveis","explanation":"Teste favorável: instrumento cujo processo de avaliação recebeu parecer favorável do CFP/SATEPSI para uso profissional nas condições pertinentes, considerando estudos científicos e normas. Teste desfavorável: instrumento sem atendimento dos requisitos técnicos exigidos ou com condições de uso não aprovadas; não deve ser empregado profissionalmente como teste psicológico enquanto permanecer desfavorável.","contrast":"Parecer favorável não é garantia de validade para qualquer pessoa ou contexto. É preciso verificar público, finalidade e manual vigente. A resposta segue a errata de gabarito enviada pela professora."},{"n":13,"question":"A reaplicação de testes psicológicos deve respeitar critérios técnicos e éticos, considerando a natureza do construto avaliado e as orientações disponíveis. Com base nessas diretrizes, assinale a alternativa correta:","options":[{"letter":"A","text":"A legislação profissional determina um prazo fixo de 12 meses para qualquer reaplicação de teste psicológico, independentemente, do construto avaliado ou das orientações do manual."},{"letter":"B","text":"O psicólogo deve seguir, obrigatoriamente, o prazo de seis meses para o reteste, pois este é o tempo universalmente aceito para evitar vieses de memória ou prática nos respondentes."},{"letter":"C","text":"A definição do intervalo para reaplicação depende, primeiramente, das orientações presentes no manual do teste; na ausência dessas informações, o profissional deve recorrer à literatura científica, considerando as especificidades do construto avaliado."},{"letter":"D","text":"O intervalo de reaplicação dos testes é livremente escolhido pelo psicólogo, não havendo necessidade de consulta a manuais ou literatura, já que sua experiência prática é suficiente para definir o prazo adequado."},{"letter":"E","text":"A reaplicação de testes psicológicos é vedada no contexto clínico, sendo permitida apenas em avaliações de concursos e processos seletivos, em função da necessidade de controle de validade nos resultados."}],"answer":"C","topic":"Reaplicação de testes","explanation":"Não existe um único intervalo obrigatório universal para todos os testes. A reaplicação depende do construto, da possibilidade de treino, do objetivo e das orientações do manual, além de riscos de exposição e aprendizagem. A alternativa C corresponde ao critério do roteiro.","contrast":"Evitar intervalo fixo imposto sem considerar o instrumento; se a avaliação exige repetição, explicar tecnicamente por que os novos resultados serão interpretáveis."},{"n":14,"question":"Assinale a alternativa que corresponde ao Tripé da Avaliação Psicológica:","options":[{"letter":"A","text":"Entrevista, análise documental e supervisão clínica."},{"letter":"B","text":"Observação, devolução e elaboração de documentos."},{"letter":"C","text":"Testagem, entrevista e observação."},{"letter":"D","text":"Testagem, elaboração de documentos e devolução."},{"letter":"E","text":"Observação, parecer psicológico e psicoterapia."}],"answer":"C","topic":"Tripé da avaliação psicológica","explanation":"O tripé apresentado no roteiro é testagem, entrevista e observação (alternativa C). São estratégias que podem se complementar, mas não significa que todos os processos exijam necessariamente as três na mesma proporção.","contrast":"Entrevista produz relato e interação; observação registra comportamentos no contexto; testes seguem protocolos e propriedades psicométricas. A integração depende da demanda."},{"n":15,"question":"Relacione a 2ª coluna de acordo com a 1ª: 1. Descrição ( ) Exposição detalhada dos dados coletados 2. Inferência ( ) Interpretação subjetiva ( ) Caminhar ( ) Estar com pressa ( ) Bocejar ( ) Estar entediado Assinale a alternativa que apresenta a sequência correta:","options":[{"letter":"A","text":"1 – 2 – 1 – 1 – 1 – 2"},{"letter":"B","text":"2 – 1 – 1 – 2 – 1 – 2"},{"letter":"C","text":"1 – 2 – 2 – 1 – 2 – 1"},{"letter":"D","text":"1 – 2 – 2 – 2 – 1 – 2"},{"letter":"E","text":"1 – 2 – 1 – 2 – 1 – 2"}],"answer":"E","topic":"Descrição versus inferência","explanation":"Descrição registra o observável: exposição dos dados, caminhar, bocejar. Inferência interpreta o que não se observa diretamente: 'está com pressa', 'está entediado', ou atribuir um estado interno. A sequência correta é 1–2–1–2–1–2, letra E.","contrast":"Uma observação como 'bocejou' não autoriza concluir automaticamente cansaço, tédio ou desinteresse. Registra-se o dado e testa-se a interpretação com outros elementos."},{"n":16,"question":"O Rapport é considerado um elemento fundamental para a eficácia da entrevista psicológica, favorecendo a relação entre entrevistador e entrevistado. Com base nas informações apresentadas, assinale a alternativa correta:","options":[{"letter":"A","text":"O rapport corresponde apenas a uma técnica inicial da entrevista, restrita ao momento de apresentação do psicólogo, sem impacto na continuidade da interação."},{"letter":"B","text":"O rapport consiste em um estado de harmonia e de confiança, sendo influenciado pela forma como o entrevistador se sente em relação ao entrevistado, aspecto que pode gerar consequências importantes no processo."},{"letter":"C","text":"Para garantir um bom rapport, basta que o entrevistador utilize termos técnicos específicos da Psicologia, mesmo que não sejam compreendidos pelo entrevistado."},{"letter":"D","text":"O rapport é construído exclusivamente a partir da postura não verbal do entrevistador, não estando relacionado ao uso da linguagem ou à clareza das informações."},{"letter":"E","text":"A manutenção do rapport independe da percepção do entrevistado, pois o que importa é apenas a intenção do entrevistador em demonstrar empatia."}],"answer":"B","topic":"Rapport e vínculo na entrevista","explanation":"Rapport envolve construir um clima de confiança, respeito, escuta e colaboração para favorecer comunicação. Não é só simpatia nem uma técnica fixa usada apenas no começo. A alternativa B traduz essa função relacional.","contrast":"Linguagem clara, postura receptiva, limites e cuidados culturais fazem parte do vínculo. É preciso observar a experiência da pessoa, não apenas a intenção do entrevistador."},{"n":17,"question":"As entrevistas psicológicas podem assumir diferentes modalidades, de acordo com seus objetivos específicos. Com base nos seus conhecimentos, assinale a alternativa correta.","options":[{"letter":"A","text":"A entrevista de triagem tem como principal objetivo o levantamento cronológico da história de vida do sujeito, sendo especialmente voltada para a infância."},{"letter":"B","text":"A entrevista de anamnese busca avaliar a demanda imediata do sujeito e, quando necessário, realizar encaminhamentos para serviços de saúde pública."},{"letter":"C","text":"A entrevista diagnóstica pode priorizar aspectos sindrômicos (descrição de sinais e sintomas) ou psicodinâmicos (descrição e compreensão do funcionamento do sujeito)."},{"letter":"D","text":"A entrevista sistêmica é voltada exclusivamente para avaliação individual, desconsiderando a análise relacional ou familiar."},{"letter":"E","text":"A entrevista de devolução caracteriza-se pela coleta de informações iniciais para estruturar o plano de trabalho do psicólogo com o paciente."}],"answer":"C","topic":"Modalidades de entrevista","explanation":"A resposta C diferencia corretamente a modalidade indicada no roteiro. Triagem identifica a demanda e possibilidades de encaminhamento; anamnese investiga a história; devolutiva comunica resultados; outras entrevistas podem focalizar relações e contextos específicos.","contrast":"Não confundir entrevista diagnóstica ou clínica com anamnese em todos os casos. A finalidade é o que define a modalidade de entrevista."},{"n":18,"question":"As entrevistas estruturada, não-estruturada e semiestruturada diferenciam-se pelo grau de liberdade do entrevistador e pela natureza das informações obtidas. Considerando seus conhecimentos, assinale a alternativa correta:","options":[{"letter":"A","text":"A entrevista estruturada se caracteriza pela ausência de roteiro fixo, privilegiando perguntas abertas e amplas, permitindo ao entrevistado direcionar o foco da conversa."},{"letter":"B","text":"A entrevista não-estruturada tem como característica central um roteiro prévio e rígido de perguntas, sendo indicada quando se busca objetividade e comparabilidade entre os dados coletados."},{"letter":"C","text":"A entrevista semiestruturada combina elementos da estruturada e da não-estruturada, pois parte de questões previamente elaboradas, mas permite flexibilidade para explorar temas emergentes conforme a necessidade."},{"letter":"D","text":"A entrevista estruturada e a semiestruturada são equivalentes, já que ambas utilizam exclusivamente perguntas abertas para explorar livremente o discurso do entrevistado."},{"letter":"E","text":"A entrevista não-estruturada é a modalidade mais indicada quando se pretende obter informações padronizadas para fins de pesquisa quantitativa, dada sua objetividade e clareza."}],"answer":"C","topic":"Estruturada, não estruturada e semiestruturada","explanation":"Estruturada segue roteiro mais fixo e comparável; não estruturada deixa maior abertura à narrativa; semiestruturada combina tópicos previstos e perguntas de aprofundamento. A alternativa C corresponde à descrição adequada do roteiro.","contrast":"A flexibilidade não dispensa planejamento nem escuta ética. Na prática, escolhe-se o grau de estrutura conforme objetivo, público e necessidade de comparabilidade."},{"n":19,"question":"Diversos instrumentos podem ser utilizados no processo de avaliação psicológica, variando quanto à forma de coleta de dados e ao tipo de construto que buscam acessar. Considerando as características das técnicas projetivas, expressivas e dos testes psicométricos, assinale a alternativa correta:","options":[{"letter":"A","text":"As técnicas projetivas apresentam estímulos totalmente estruturados, claros e objetivos, de modo a evitar interpretações subjetivas e reduzir a influência da personalidade do sujeito."},{"letter":"B","text":"As técnicas expressivas buscam investigar aspectos da personalidade a partir da análise de padrões de movimento, ritmo e expressão corporal, em vez de estímulos verbais ou gráficos ambíguos."},{"letter":"C","text":"Os testes psicométricos se baseiam na apresentação de estímulos ambíguos, nos quais o sujeito projeta conteúdos latentes de sua personalidade por meio de respostas não padronizadas."},{"letter":"D","text":"As técnicas projetivas e expressivas têm em comum o caráter padronizado e normativo das escalas, as quais possibilitam avaliação quantitativa dos traços de personalidade."},{"letter":"E","text":"Os testes psicométricos não consideram as respostas dadas pelo sujeito, mas apenas observações externas do avaliador sobre seu comportamento durante a aplicação."}],"answer":"B","topic":"Técnicas projetivas, expressivas e psicométricas","explanation":"A letra B identifica técnicas expressivas por manifestações como movimento, ritmo ou características da expressão. Projetivas costumam trabalhar com estímulos menos estruturados e interpretações apoiadas no referencial técnico; testes psicométricos buscam mensuração padronizada com evidências de precisão, validade e normas.","contrast":"A e C invertem projetivo e psicométrico; D atribui a todas as técnicas o mesmo modelo normativo; E ignora respostas do próprio avaliado. Técnica nenhuma dispensa limites éticos e evidência apropriada."}]}];
